import matplotlib.pyplot as plt
import numpy as np

# Load the pose data generated by C++
try:
    data = np.loadtxt('poses.csv', delimiter=',', skiprows=1)
    if data.ndim == 1:  # Handle case where there's only 1 row
        data = np.array([data])
except Exception as e:
    print(f"Error loading poses.csv: {e}")
    exit(1)

# Set up the 3D interactive plot window
fig = plt.figure(figsize=(9, 7))
ax = fig.add_subplot(projection='3d')

# Loop through each pose and plot it
for row in data:
    x, y, z, roll, pitch, yaw = row
    
    # Plot the position point in red
    ax.scatter(x, y, z, color='red', s=120, label='Position')
    
    # Calculate heading direction based on Yaw orientation
    dx = np.cos(yaw)
    dy = np.sin(yaw)
    dz = 0.0
    
    # Draw a blue arrow pointing in the direction the robot is facing
    ax.quiver(x, y, z, dx, dy, dz, length=0.8, color='blue', normalize=True, linewidth=2, label='Heading (Yaw)')

# Graph styling and axis bounds
ax.set_xlabel('X Axis (Forward/Back)')
ax.set_ylabel('Y Axis (Left/Right)')
ax.set_zlabel('Z Axis (Up/Down)')
ax.set_xlim([-1, 3])
ax.set_ylim([-1, 3])
ax.set_zlim([0, 2])
ax.set_title('Simple3D Interactive Visualizer')

# Clean up legend duplicates if multiple points exist
handles, labels = plt.gca().get_legend_handles_labels()
by_label = dict(zip(labels, handles))
ax.legend(by_label.values(), by_label.keys())

print("Opening 3D interactive plot window... (Click and drag to rotate)")
plt.show()